-- The event being handled, so a fact only latches on its own kind of event.
local kind = nil

local function slot_fact(id, event_kind, slot)
    return {id = id, observe = function(context, _, event)
        return kind == event_kind and lib.is_slot(context, event, slot)
    end}
end

-- Arm a trigger and remember it, so its first report can disarm it.
local function arm(context, id)
    context:set_variable("armed/" .. id, true)
    context:slot(id):fire_trigger()
end

-- Start an authored scene with its cast: spawn = true has the host spawn the scene's own
-- squads and bind its actors to them. Without it the scene runs with nobody in it. A scene
-- whose cast the host cannot work out refuses spawn = true with an error; that one is started
-- bare instead, and a debug variable on the Mission state page says so.
local function start_scene(context, id, name)
    local scene = context:scene(id)
    if not pcall(function() scene:activate{spawn = true} end) then
        context:set_variable("debug.scene." .. name, "started without a cast")
        scene:activate{}
    end
end

-- Marks for local triggers, outputs and "whichever finishes first" joins. They name the attempt, so a restart forgets them.
local function mark(name)
    return function(context) context:set_variable(name, context.attempt_generation) end
end
local function marked(name)
    return function(context, state) return state:variable(name) == context.attempt_generation end
end

-- Areas, in order. The player lands in the first.
local FIRST = input.state_underwatch

-- An object the player must use spawns with its area unless it is kept out; it is kept out
-- until the step that asks for it sends its interaction row.
local OMIT = {input.scout_rifle_interactable}

-- Opening cutscenes: each plays in its own state, in order, before the first leg. The spawn
-- is held meanwhile, so no body is placed inside the first leg's geometry.
local INTRO = {
    {state = input.state_intro_cinematic, cinematic = input.prefab_hro_cinematic},
}
local PLAYING, ENDED = 1, 2
local function intro_key(index) return "m.intro." .. index end
local function intro_done(state) return #INTRO == 0 or state:variable(intro_key(#INTRO)) == ENDED end
local function start_intro(context, state, region)
    for index, cut in ipairs(INTRO) do
        if cut.state.region_index == region and state:variable(intro_key(index)) == nil then
            context:set_variable(intro_key(index), PLAYING)
            context:slot(cut.cinematic):set_cinematic_active{active = true}
        end
    end
end
local function end_intro(context, state, index)
    if state:variable(intro_key(index)) == ENDED then return end
    context:set_variable(intro_key(index), ENDED)
    -- Stop before the state change, or the rebuilt component plays the cutscene again.
    context:slot(INTRO[index].cinematic):set_cinematic_active{active = false}
    if index < #INTRO then
        context:select_state(INTRO[index + 1].state)
    else
        context:select_state(FIRST, OMIT)
        context:hold_spawn{active = false}
    end
end
-- End, skip and a refused start all name the cinematic that was playing.
local function end_reported_intro(context, state, event)
    for index, cut in ipairs(INTRO) do
        if state:variable(intro_key(index)) == PLAYING and lib.is_slot(context, event, cut.cinematic) then
            end_intro(context, state, index)
        end
    end
end

