-- The mission flow: what the player is asked to do, in order.
local M

M = flow.new{
    key = "m",
    facts = {
        {id = "arrival", observe = function(_, state, event)
            local region = FIRST.region_index
            if event.entered == true and event.held_region_index == region then return true end
            return #INTRO > 0 and intro_done(state) and event.region_index == region
        end},
        {id = "leg.underwatch", observe = function(_, _, event)
            local region = input.state_underwatch.region_index
            return event.region_index == region or (event.entered == true and event.held_region_index == region)
        end},
        slot_fact("home.t0", "player_trigger", input.pt_player_near_shaxx),
        {id = "gear.used", observe = function(context, state, event)
            return kind == "object_interacted" and M:started(context, state, "gear") and lib.is_slot(context, event, input.scout_rifle_interactable)
        end},
        slot_fact("find.t0", "player_trigger", input.pt_goto_military),
    },
    steps = {
        -- The player lands
        {id = "arrival", await = flow.fact("arrival")},

        -- Step home
        {id = "home", after = {"arrival"}, run = function(context)
            GOALS[1](context)
            context:set_variable("m.goal", 1)
            mark("m.on.t254")(context)   -- run scene cast
            mark("m.on.t344")(context)   -- run scene cayde
            mark("m.on.t297")(context)   -- run scene first_contact
            context:slot(input.m_dialog_sensor_80b50913):play_dialogue_cue{cue = input.cue_1}
            arm(context, input.pt_player_near_shaxx)
        end, await = flow.fact("home.t0")},

        -- Step gear
        {id = "gear", after = {"home"}, run = function(context)
            context:slot(input.scout_rifle_interactable):set_interactable_object{used = true}
            GOALS[2](context)
            context:set_variable("m.goal", 2)
            context:slot(input.d_gun_door):transition{transition = context.sdk.device_transitions.open}
            mark("m.on.t301")(context)   -- run scene post_gun
        end, await = flow.fact("gear.used")},

        -- Step find
        {id = "find", after = {"gear"}, run = function(context)
            GOALS[3](context)
            context:set_variable("m.goal", 3)
            context:slot(input.m_dialog_sensor_80b50913):play_dialogue_cue{cue = input.cue_30, filter = context:slot(input.slot_0004_80b5168c)}
            arm(context, input.pt_goto_military)
        end, await = flow.fact("find.t0")},
    },
}

