local GRAPHS = {M, scene_cast, scene_first_contact, scene_post_gun, scene_cayde}

-- Two passes: a step that runs a scene, and a scene whose output ends a step, both take
-- effect in the same callback.
local function advance(context, state)
    for _ = 1, 2 do
        for _, graph in ipairs(GRAPHS) do graph:advance(context, state) end
    end
end
local function handle(name, context, state, event)
    kind = name
    for _, graph in ipairs(GRAPHS) do graph:handle(context, state, event) end
    advance(context, state)
    kind = nil
end
-- The player now holds an area: arm what is waiting there, and show the goal again.
local function entered(name, context, state, event)
    local goal = state:variable("m.goal")
    for _, id in ipairs(TRIGGERS) do
        if state:variable("armed/" .. id) == true then context:slot(id):fire_trigger() end
    end
    handle(name, context, state, event)
    if goal ~= nil and state:variable("m.goal") == goal and GOALS[goal] ~= nil then GOALS[goal](context) end
end

return {
    initial_state = {region_index = (INTRO[1] and INTRO[1].state or FIRST).region_index, omit = OMIT},
    on_start = function(context, state)
        if #INTRO > 0 then context:hold_spawn{active = true} end
        advance(context, state)
    end,
    -- A reattach lands in the world, so a cutscene still marked playing is ended, not replayed.
    on_load = function(context, state)
        for index in ipairs(INTRO) do
            if state:variable(intro_key(index)) == PLAYING then end_intro(context, state, index) end
        end
        if #INTRO > 0 and intro_done(state) and not M:fact(context, state, "arrival") then context:select_state(FIRST, OMIT) end
        advance(context, state)
    end,
    -- Only the arrival answer counts. A pending leg report names a region the client has not loaded.
    on_event_client_state_changed = function(context, state, event)
        if event.entered == true then
            start_intro(context, state, event.held_region_index)
            entered("client_state_changed", context, state, event)
        end
    end,
    on_event_region_changed = function(context, state, event)
        start_intro(context, state, event.region_index)
        entered("region_changed", context, state, event)
    end,
    on_event_player_trigger = function(context, state, event)
        -- An armed trigger reports on every update; disarm it on the first one.
        local slot = event.slot
        if slot ~= nil and state:variable("armed/" .. slot.id) == true then
            context:clear_variable("armed/" .. slot.id)
            slot:disarm_trigger()
        end
        handle("player_trigger", context, state, event)
    end,
    on_event_squad_state = function(context, state, event) handle("squad_state", context, state, event) end,
    on_event_object_interacted = function(context, state, event) handle("object_interacted", context, state, event) end,
    on_event_scene_finished = function(context, state, event) handle("scene_finished", context, state, event) end,
    on_event_cinematic_terminated = function(context, state, event)
        end_reported_intro(context, state, event)
        handle("cinematic_terminated", context, state, event)
    end,
    on_event_cinematic_skip_requested = function(context, state, event)
        end_reported_intro(context, state, event)
        handle("cinematic_skip_requested", context, state, event)
    end,
}
